/** Public presentation only. A parsed object never authenticates its sender. */
export type ProductIdentity = Readonly<{id:string;username:string}>;
export type ProductCapabilities = Readonly<{passwordLogin:boolean;phoneLogin:boolean;passwordRecovery:boolean;cloudSync:false}>;

// Product IDs are generated by server randomUUID(): canonical lowercase UUIDv4.
export const PRODUCT_USER_ID=/^usr_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
const object=(value:unknown):value is Record<string,unknown>=>!!value&&typeof value==='object'&&!Array.isArray(value);

export function parseProductIdentity(value:unknown):ProductIdentity|null {
  if(!object(value)||Object.keys(value).sort().join(',')!=='id,username')return null;
  const {id,username}=value;
  return typeof id==='string'&&PRODUCT_USER_ID.test(id)&&typeof username==='string'&&/^[a-z0-9_]{3,32}$/.test(username)
    ?Object.freeze({id,username}):null;
}

export function productResponseIdentity(value:unknown):ProductIdentity|null {
  return object(value)?parseProductIdentity(value.user):null;
}

export function parseProductCapabilities(value:unknown):ProductCapabilities|null {
  if(!object(value)||typeof value.passwordLogin!=='boolean'||typeof value.phoneLogin!=='boolean'||
    value.passwordRecovery!==undefined&&typeof value.passwordRecovery!=='boolean')return null;
  return Object.freeze({passwordLogin:value.passwordLogin,phoneLogin:value.phoneLogin,
    passwordRecovery:value.passwordRecovery===true,cloudSync:false});
}

export type ProductCredentials={username:string;password:string};
export type CredentialValidation={ok:true;credentials:ProductCredentials}|{ok:false;message:string};

export function validateProductCredentials(username:string,password:string,confirmation?:string):CredentialValidation {
  if(/[^\x00-\x7f]/.test(username)||!/^[a-zA-Z0-9_]{3,32}$/.test(username.trim()))return {ok:false,
    message:'用户名须为 3–32 个英文字母、数字或下划线，大小写不区分，首尾空白会去除。'};
  const length=[...password].length;
  if(length<15||length>128)return {ok:false,message:'密码须为 15–128 个字符，首尾空白属于密码。'};
  if(confirmation!==undefined&&password!==confirmation)return {ok:false,message:'两次输入的密码不一致。'};
  return {ok:true,credentials:{username:username.trim().toLowerCase(),password}};
}
